#[cfg(test)]
mod tests {
    use crate::owned_command::bf16_gemm::PinnedCapturedBf16Cubin;
    #[test]
    fn selected_images_preserve_whole_identity_and_unobserved_provenance() {
        for kind in [
            PinnedCapturedBf16Cubin::ShortHfFaCausalCombineSm80,
            PinnedCapturedBf16Cubin::ShortHfFaSplitCombineSm80,
            PinnedCapturedBf16Cubin::ShortHfCutlassBf16Sm80,
            PinnedCapturedBf16Cubin::Cohort2BAmpere64SlicedSm80,
        ] {
            let r = kind.capture();
            assert_eq!(r.binary_sm, 80);
            assert!(!r.preserved_input_resource_equal);
            assert!(!r.immutable_carrier_membership_proven);
            assert!(!r.runtime_derivation_proven);
            assert!(r.reference_driver_sha256.is_empty());
            assert!(
                kind.require_image(r.image_bytes, r.image_sha256, 80)
                    .is_ok()
            );
            for bit in 0..256 {
                let mut sha = r.image_sha256;
                sha[bit / 8] ^= 1 << (bit % 8);
                assert!(kind.require_image(r.image_bytes, sha, 80).is_err());
            }
            for bytes in [0, r.image_bytes - 1, r.image_bytes + 1, usize::MAX] {
                assert!(kind.require_image(bytes, r.image_sha256, 80).is_err());
            }
            assert!(
                kind.require_image(r.image_bytes, r.image_sha256, 86)
                    .is_err()
            );
        }
    }
}
